document.addEventListener("DOMContentLoaded", () => {
    gsap.registerPlugin(ScrollTrigger);
  
    const counters = document.querySelectorAll("[data-counter]");
  
    counters.forEach(el => {
      // ambil target dari text
      const target = Number(el.textContent.replace(/[^0-9.-]/g, ""));
      if (isNaN(target)) return;
  
      // ambil semua config dari dataset (dengan fallback)
      const duration = parseFloat(el.dataset.duration) || 1.5;
      const delay = parseFloat(el.dataset.delay) || 0;
      const ease = el.dataset.ease || "power1.out";
      const start = el.dataset.start || "top 80%";
      const once = el.dataset.once !== "false"; // default true
  
      gsap.fromTo(el,
        { innerText: 0 },
        {
          innerText: target,
          duration: duration,
          delay: delay,
          ease: ease,
          snap: { innerText: 1 },
          scrollTrigger: {
            trigger: el,
            start: start,
            once: once
          },
          onUpdate() {
            el.innerText = Math.floor(el.innerText);
          }
        }
      );
    });
  });